    {
        "name": "Flea Infestation",
        "name_ja": "ノミ寄生",
        "symptoms": {"itching", "scratching", "hair_loss", "skin_redness", "visible_parasites"},
        "description": "Flea Infestation is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "外部寄生虫による掻痒。",
        "urgency": "low",
        "recommended_tests": ["physical_exam"],
        "causes": "Caused by parasitic organisms infecting dermatological tissue. Transmission occurs via ingestion of infective stages (eggs, oocysts, larvae), direct contact, vector-borne routes, or percutaneous penetration. Predisposing factors include poor sanitation, outdoor exposure, immunosuppression, and stress. In hamster, the omnivorous diet may expose them to specific parasitic life cycles.",
        "causes_ja": "皮膚組織に感染する寄生虫が原因。感染期（卵・オーシスト・幼虫）の経口摂取・直接接触・ベクター・経皮侵入で伝播。不衛生・屋外曝露・免疫抑制・ストレスが素因。ハムスターの食性が特定の寄生虫生活環への曝露を増加させうる。",
        "pathophysiology": "The parasite establishes infection in dermatological tissue of hamster through ingestion, skin penetration, or vector-mediated transmission. Parasitic organisms damage host tissue through direct mechanical injury, nutrient competition, and immunopathological responses. Eosinophilic and granulomatous inflammation develops around parasitic stages. Chronic infection leads to tissue fibrosis and organ dysfunction. The small rodent with cheek pouches characteristics of hamster may influence parasite lifecycle completion and host susceptibility.",
        "pathophysiology_ja": "寄生虫は経口摂取・皮膚穿通・ベクター媒介によりハムスターの皮膚組織に感染を確立する。寄生体は直接的な機械的損傷・栄養競合・免疫病理学的反応を通じて宿主組織を損傷する。寄生体段階の周囲に好酸球性・肉芽腫性炎症が発生する。慢性感染は組織線維化と臓器機能障害に至る。",
        "treatment": "Treatment of flea infestation in hamster involves specific therapy directed at the underlying cause combined with supportive care. Fluid therapy, nutritional support, pain management (species-appropriate analgesics), and environmental optimization are fundamental. Specific treatments depend on diagnosis and may include antimicrobials, antiparasitics, antifungals, surgical intervention, or supportive care. Consultation with an exotic animal veterinarian is recommended.",
        "treatment_ja": "ハムスターにおけるノミ寄生の治療: 原因の鑑別（真菌培養/皮膚掻爬/細胞診）。感染性は適切な抗菌薬/抗真菌薬。アレルギー性は原因除去+対症療法。環境改善・衛生管理。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "Prognosis depends on severity, timeliness of treatment, and response to therapy. Early intervention generally improves outcomes.",
        "prognosis_ja": "適切な駆虫薬治療で予後は一般的に良好。重度感染や免疫不全ハムスターでは予後不良となりうる。環境消毒と再感染予防が長期的な予後改善に重要。定期的な糞便検査と予防的駆虫が推奨される。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    # ── 腫瘍 ──
    {
        "name": "Mammary Tumor",
        "name_ja": "乳腺腫瘍",
        "symptoms": {"skin_lump", "mammary_mass", "weight_loss", "lethargy"},
        "description": "Mammary Tumor is a neoplastic condition characterized by abnormal cell proliferation that may be benign or malignant.",
        "description_ja": "メスのハムスターに多い腫瘍で、良性または悪性。",
        "urgency": "high",
        "recommended_tests": ["cytology", "biopsy", "radiography"],
        "causes": "Caused by neoplastic transformation of mammary gland tissue, common in both male and female hamsters. Hormonal influences and genetic predisposition are contributing factors.",
        "causes_ja": "ハムスターにおける乳腺腫瘍の原因: メスのハムスターに多い腫瘍で、良性または悪性。",
        "pathophysiology": "Accumulated genetic mutations lead to uncontrolled cell proliferation, evasion of apoptosis, and potential metastatic spread. Tumor growth causes tissue compression, invasion, and paraneoplastic effects.",
        "pathophysiology_ja": "乳腺腫瘍はハムスターにおける腫瘍性疾患である。癌遺伝子、腫瘍抑制遺伝子、DNA修復機構における遺伝子変異の蓄積により腫瘍性形質転換が生じる。制御不能な細胞増殖により腫瘍が形成され、局所組織への浸潤・破壊の可能性がある。悪性腫瘍はリンパ行性または血行性に転移しうる。高カルシウム血症、悪液質、免疫調節障害などの腫瘍随伴症候群が原発腫瘍に伴い、罹患率に寄与することがある。",
        "treatment": "Treatment options include surgical excision, chemotherapy, radiation therapy, and palliative care depending on tumor type, location, and staging. Supportive care and pain management are essential.",
        "treatment_ja": "ハムスターにおける乳腺腫瘍の治療: 腫瘍の評価（病理組織検査）に基づく治療計画。外科的切除が可能な場合は第一選択。術後の疼痛管理と栄養サポート。化学療法は腫瘍の種類に応じて検討。緩和ケア（疼痛管理・QOL維持）。",
        "prevention": "Prevention is limited for most neoplastic conditions. Regular health examinations facilitate early detection. Spaying/neutering may reduce risk of hormone-dependent tumors.",
        "prevention_ja": "乳腺腫瘍の予防は限定的であるが、ホルモン依存性腫瘍軽減のための避妊・去勢手術、既知の発癌物質の回避、早期発見のための定期健診、適正体型の維持、該当する場合は遺伝的素因軽減のための責任ある繁殖が含まれる。",
        "prognosis": "Prognosis depends on tumor type, staging, and response to treatment. Complete surgical excision of localized tumors improves outcomes. Metastatic disease carries a guarded to poor prognosis.",
        "prognosis_ja": "乳腺腫瘍の予後: 腫瘍の種類、病期、転移の有無により予後は大きく異なる。早期発見・早期治療で予後改善。悪性腫瘍は一般的に予後要注意〜不良。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
