    {
        "name": "Amyloidosis",
        "name_ja": "アミロイドーシス",
        "symptoms": {"weight_loss", "lethargy", "increased_thirst", "edema", "appetite_loss"},
        "description": "Amyloidosis is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "腎臓や肝臓へのアミロイドタンパク質の沈着。",
        "urgency": "high",
        "recommended_tests": ["blood_chemistry", "biopsy", "urinalysis"],
        "causes": "Caused by progressive deterioration of multisystemic tissue due to aging, chronic wear, or cumulative damage. Contributing factors include genetic predisposition, chronic inflammation, oxidative stress, and suboptimal husbandry conditions. In hamster, captive management practices and dietary factors may accelerate degenerative changes.",
        "causes_ja": "加齢・慢性的摩耗・累積的損傷による多臓器/全身組織の進行性劣化が原因。遺伝的素因・慢性炎症・酸化ストレス・不適切な飼育条件が寄与。ハムスターの飼育管理と食事因子が変性変化を加速しうる。",
        "pathophysiology": "Progressive degenerative changes in multisystemic tissue of hamster involve gradual loss of cellular structure and function. Mechanisms include oxidative stress, chronic inflammation, cellular senescence, and impaired tissue repair. Age-related changes, cumulative environmental insults, and genetic predisposition contribute to disease progression. In hamster, degenerative conditions may be exacerbated by captive management practices and dietary factors.",
        "pathophysiology_ja": "ハムスターの多臓器/全身組織における進行性変性変化は、細胞構造と機能の漸進的喪失を伴う。酸化ストレス・慢性炎症・細胞老化・組織修復障害が関与する。加齢変化・累積的環境侵襲・遺伝的素因が疾患進行に寄与する。飼育管理と食事要因が変性疾患を悪化させうる。",
        "treatment": "Treatment of amyloidosis in hamster involves specific therapy directed at the underlying cause combined with supportive care. Fluid therapy, nutritional support, pain management (species-appropriate analgesics), and environmental optimization are fundamental. Specific treatments depend on diagnosis and may include antimicrobials, antiparasitics, antifungals, surgical intervention, or supportive care. Consultation with an exotic animal veterinarian is recommended.",
        "treatment_ja": "ハムスターにおけるアミロイドーシスの治療: 原因の鑑別診断に基づく特異的治療。支持療法（輸液・栄養・疼痛管理）。環境管理。定期的なモニタリングと治療調整。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "Prognosis depends on severity, timeliness of treatment, and response to therapy. Early intervention generally improves outcomes.",
        "prognosis_ja": "変性疾患の予後は進行速度と管理可能性に依存する。緩徐進行性の場合、適切な対症療法とQOL管理で長期生存が可能。急速進行性の場合は予後不良。定期的な再評価と治療調整が重要。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
    {
        "name": "Hepatic Lipidosis",
        "name_ja": "肝リピドーシス（脂肪肝）",
        "symptoms": {"lethargy", "appetite_loss", "weight_loss", "jaundice", "abdominal_distension"},
        "description": "Hepatic Lipidosis is a hepatic condition affecting liver function and metabolism.",
        "description_ja": "肥満や食欲不振による肝臓への脂肪蓄積。",
        "urgency": "high",
        "recommended_tests": ["blood_chemistry", "ultrasound"],
        "causes": "Caused by excessive fat accumulation in hepatocytes due to obesity, sudden anorexia, nutritional imbalance, or metabolic dysfunction. Obese hamsters and pregnant females are predisposed.",
        "causes_ja": "ハムスターにおける肝リピドーシスの原因: 臓器機能障害、ホルモンバランス異常、食事因子、遺伝的素因、加齢による代謝・内分泌経路の調節障害。肥満と運動不足が寄与しうる。",
        "pathophysiology": "Hepatocellular damage impairs metabolic, synthetic, and detoxification functions. Progressive injury leads to inflammation, fibrosis, and potential hepatic failure with systemic consequences.",
        "pathophysiology_ja": "肝リピドーシスはハムスターにおける代謝・内分泌疾患である。基礎病態はホルモンのフィードバックループ、酵素活性、または基質代謝の調節障害を伴う。循環ホルモン、電解質、代謝中間体のバランス異常が複数の臓器系にわたる細胞機能に影響を及ぼす。代償機構が一時的に恒常性を維持するが、最終的に代償不全に陥り、進行性の臨床的悪化と多臓器への影響を引き起こす。",
        "treatment": "Nutritional support (assisted feeding for hepatic lipidosis), hepatoprotectants (SAMe, ursodiol), IV fluid therapy, anti-emetics, and treatment of underlying cause.",
        "treatment_ja": "ハムスターにおける肝リピドーシスの治療は基礎となるホルモン・代謝異常を標的とする。ホルモン補充療法または抑制療法により生理的バランスを回復する。食事療法で代謝疾患の栄養面に対処する。ホルモンレベル、血糖、電解質、臓器機能マーカーの定期的モニタリングにより用量調整を行う。二次的合併症（臓器障害、感染）の併行管理が不可欠である。長期または生涯にわたる治療が必要な場合がある。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "肝リピドーシスの予防には適切な食事設計、血液検査を含む定期的な健康モニタリング、健康体重の維持、過剰なおやつや不適切な食事の回避、無症候性変化の早期発見時の迅速な介入が含まれる。",
        "prognosis": "Variable. Hepatic lipidosis has a fair prognosis with early aggressive nutritional support. Chronic liver disease is guarded depending on underlying cause and degree of fibrosis.",
        "prognosis_ja": "肝リピドーシス（脂肪肝）の予後: 原因と重症度による。急性肝疾患は早期治療で回復可能。慢性肝疾患は長期管理で QOL 維持可能。肝不全は予後不良。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
