    {
        "name": "Hamster Polyomavirus",
        "name_ja": "ハムスターポリオーマウイルス",
        "symptoms": {"skin_lump", "hair_loss", "weakness", "lethargy"},
        "description": "Hamster Polyomavirus is a viral disease that may cause acute or chronic illness with variable clinical presentation.",
        "description_ja": "皮膚腫瘍やリンパ腫を引き起こすウイルス感染。",
        "urgency": "high",
        "recommended_tests": ["biopsy", "histopathology"],
        "causes": "Infection by viral pathogens through direct contact, aerosol transmission, fomite exposure, or vector-borne routes. Immunosuppression, stress, overcrowding, and inadequate vaccination increase susceptibility.",
        "causes_ja": "ハムスターにおけるハムスターポリオーマウイルスの原因: ウイルス病原体による感染。直接接触、飛沫・空気感染、媒介物、ベクター媒介が感染経路。免疫抑制、ストレス、過密飼育、ワクチン未接種が感受性を高める。",
        "pathophysiology": "Hamster Polyomavirus is caused by viral infection. Hamster Polyomavirus The virus enters host cells through specific receptor-mediated mechanisms, hijacking cellular machinery for replication. This leads to direct cytopathic effects including cell lysis, apoptosis, and tissue necrosis in target organs. The host immune response—involving both innate (interferons, NK cells) and adaptive (antibody, cell-mediated) pathways—may contribute to immunopathology. Viremia can disseminate the pathogen to multiple organ systems, and immunosuppression may predispose to secondary bacterial or fungal infections.",
        "pathophysiology_ja": "ハムスターポリオーマウイルスはハムスターにおけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Treatment of hamster polyomavirus in hamster is primarily supportive, as most viral infections lack specific antiviral therapy. Fluid therapy maintains hydration and corrects electrolyte imbalances. Antipyretics and analgesics manage fever and discomfort. Broad-spectrum antibiotics prevent or treat secondary bacterial infections. Nutritional support—including assisted feeding if anorexic—is essential. Immunostimulants or interferons may be beneficial in some cases. Isolation of affected individuals prevents transmission to susceptible contacts.",
        "treatment_ja": "特異的抗ウイルス治療はない。支持療法：輸液（温生理食塩水SC）、保温と安静、シリンジによる強制給餌。二次性細菌感染の予防にエンロフロキサシン5-10 mg/kg PO q12h。メロキシカム0.2-1 mg/kg PO q24hで疼痛管理。感染動物の隔離と検疫。環境の消毒。",
        "prevention": "Prevention includes vaccination where available, quarantine of new animals, biosecurity measures, proper hygiene, and avoiding contact with infected animals.",
        "prevention_ja": "ハムスターポリオーマウイルスの予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "Variable depending on viral agent and host immunity. Mild infections often resolve with supportive care. Severe systemic viral diseases carry a guarded to poor prognosis.",
        "prognosis_ja": "ハムスターポリオーマウイルスの予後: ウイルスの種類と宿主の免疫状態による。ワクチン予防可能な疾患は予防が最善。支持療法で多くが回復可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"young"},
    },
