    {
        "name": "Osteoarthritis",
        "name_ja": "変形性関節症",
        "symptoms": {"lameness", "reduced_activity", "stiffness", "pain"},
        "description": "Osteoarthritis is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "高齢ハムスターの変性性関節疾患。",
        "urgency": "moderate",
        "recommended_tests": ["radiography", "physical_exam"],
        "causes": "Caused by progressive deterioration of musculoskeletal tissue due to aging, chronic wear, or cumulative damage. Contributing factors include genetic predisposition, chronic inflammation, oxidative stress, and suboptimal husbandry conditions. In hamster, captive management practices and dietary factors may accelerate degenerative changes.",
        "causes_ja": "加齢・慢性的摩耗・累積的損傷による筋骨格系組織の進行性劣化が原因。遺伝的素因・慢性炎症・酸化ストレス・不適切な飼育条件が寄与。ハムスターの飼育管理と食事因子が変性変化を加速しうる。",
        "pathophysiology": "Progressive degenerative changes in musculoskeletal tissue of hamster involve gradual loss of cellular structure and function. Mechanisms include oxidative stress, chronic inflammation, cellular senescence, and impaired tissue repair. Age-related changes, cumulative environmental insults, and genetic predisposition contribute to disease progression. In hamster, degenerative conditions may be exacerbated by captive management practices and dietary factors.",
        "pathophysiology_ja": "ハムスターの筋骨格系組織における進行性変性変化は、細胞構造と機能の漸進的喪失を伴う。酸化ストレス・慢性炎症・細胞老化・組織修復障害が関与する。加齢変化・累積的環境侵襲・遺伝的素因が疾患進行に寄与する。飼育管理と食事要因が変性疾患を悪化させうる。",
        "treatment": "Treatment of osteoarthritis in hamster involves specific therapy directed at the underlying cause combined with supportive care. Fluid therapy, nutritional support, pain management (species-appropriate analgesics), and environmental optimization are fundamental. Specific treatments depend on diagnosis and may include antimicrobials, antiparasitics, antifungals, surgical intervention, or supportive care. Consultation with an exotic animal veterinarian is recommended.",
        "treatment_ja": "ハムスターにおける変形性関節症の治療: 原因の鑑別診断に基づく特異的治療。支持療法（輸液・栄養・疼痛管理）。環境管理。定期的なモニタリングと治療調整。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "Prognosis depends on severity, timeliness of treatment, and response to therapy. Early intervention generally improves outcomes.",
        "prognosis_ja": "変性疾患の予後は進行速度と管理可能性に依存する。緩徐進行性の場合、適切な対症療法とQOL管理で長期生存が可能。急速進行性の場合は予後不良。定期的な再評価と治療調整が重要。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
