    {
        "name": "Vitamin Deficiency",
        "name_ja": "ビタミン欠乏症",
        "symptoms": {"hair_loss", "rough_coat", "lethargy", "weight_loss", "muscle_wasting"},
        "description": "Vitamin Deficiency is a nutritional or metabolic disorder caused by dietary imbalance or deficiency.",
        "description_ja": "ビタミンD、E、B群の欠乏。",
        "urgency": "moderate",
        "recommended_tests": ["dietary_review", "blood_chemistry"],
        "causes": "Deficiency of vitamins D, E, or B complex.",
        "causes_ja": "ハムスターにおけるビタミン欠乏症の原因: ビタミンD、E、B群の欠乏。",
        "pathophysiology": "Vitamin Deficiency is a nutritional disorder. Deficiency of vitamins D, E, or B complex. The condition results from inadequate intake, malabsorption, or excessive supplementation of specific nutrients. Deficiency states impair biochemical pathways dependent on the affected nutrient as cofactor or substrate, leading to cellular dysfunction. Excess states cause toxicity through accumulation in tissues or disruption of nutrient interactions. Species-specific dietary requirements make proper nutritional management critical for prevention.",
        "pathophysiology_ja": "ビタミン欠乏症はハムスターにおける栄養障害である。特定の栄養素の不十分な摂取、吸収不良、または過剰摂取により生じる。欠乏状態では、影響を受けた栄養素を補因子または基質として必要とする生化学的経路が障害され、細胞機能障害を引き起こす。過剰状態では組織への蓄積や栄養素間相互作用の障害により毒性が生じる。種特異的な食事要求により、適切な栄養管理が予防に不可欠である。",
        "treatment": "Treatment of vitamin deficiency in hamster centers on correcting the nutritional imbalance. Deficiency states require supplementation of the specific nutrient through dietary correction or therapeutic supplementation. Excess states require dietary restriction and supportive care for organ damage. Gradual correction prevents refeeding syndrome in malnourished animals. Species-specific dietary requirements must guide long-term nutritional planning. Regular reassessment ensures adequate without excessive intake.",
        "treatment_ja": "ハムスターにおけるビタミン欠乏症の治療は栄養バランスの是正が中心となる。欠乏状態では食事の改善または治療的サプリメンテーションにより特定の栄養素を補充する。過剰状態では食事制限と臓器障害に対する支持療法を行う。栄養不良動物ではリフィーディング症候群予防のため段階的に是正する。種特異的な食事要求に基づく長期栄養計画を立案する。過不足のない摂取を確保するため定期的に再評価する。",
        "prevention": "Prevention includes providing a balanced, species-appropriate diet with adequate vitamins and minerals, appropriate UVB lighting where needed, and regular nutritional assessment.",
        "prevention_ja": "ビタミン欠乏症の予防には全ての栄養要求を満たす種に適した食事設計、単一食品のみの食事の回避、獣医師との定期的な食事内容の見直し、必要時の適切なサプリメンテーション、種固有の栄養ニーズに関する知識が必要である。",
        "prognosis": "Good with dietary correction and supplementation. Clinical signs typically improve within weeks of appropriate nutrition. Severe cases may have residual deficits.",
        "prognosis_ja": "ビタミン欠乏症の予後: 早期発見と適切な治療で多くの疾患は予後良好。慢性疾患は定期的モニタリングと治療調整で長期管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
    {
        "name": "Antibiotic Toxicity",
        "name_ja": "抗生物質中毒",
        "symptoms": {"diarrhea", "appetite_loss", "lethargy", "dehydration", "sudden_death"},
        "description": "Antibiotic Toxicity is a toxicological condition caused by exposure to harmful substances.",
        "description_ja": "ハムスターに有害な抗生物質による致死的菌交代現象。",
        "urgency": "emergency",
        "recommended_tests": ["medication_review", "fecal_exam"],
        "causes": "Caused by administration of antibiotics that disrupt normal cecal and intestinal flora, particularly penicillin, ampicillin, erythromycin, lincomycin, and cephalosporins, leading to fatal Clostridial overgrowth.",
        "causes_ja": "消化器系に影響する有毒物質への曝露が原因。一般的な毒素：重金属（鉛・亜鉛）・家庭用化学物質・有毒植物・農薬・薬物（不適切使用・偶発曝露）・環境汚染物質。ハムスターの食性と生理学的特性が毒素の吸収・代謝・感受性に影響しうる。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "ハムスターの消化器系組織に影響する中毒曝露は、有害物質の経口摂取・吸入・経皮吸収に起因する。毒素は直接的な細胞毒性・酸化ストレス・ミトコンドリア機能障害・重要酵素経路の攪乱を介して細胞を損傷する。ハムスターの食性と生理学的特性が毒素の吸収と代謝に影響しうる。臓器特異的損傷は毒素の薬物動態と標的臓器親和性に依存する。",
        "treatment": "Treatment includes decontamination (if recent ingestion), specific antidotes where available, supportive care, fluid therapy, and monitoring of organ function.",
        "treatment_ja": "ハムスターにおける抗生物質中毒の治療: 輸液で脱水補正。消化管運動促進薬。制吐薬。疼痛管理。食事管理（繊維質の確保）。原因に応じた特異的治療。",
        "prevention": "Prevention includes removing access to toxic substances, using pet-safe products, proper storage of medications and chemicals, and educating owners about common toxins.",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "Prognosis depends on severity, timeliness of treatment, and response to therapy. Early intervention generally improves outcomes.",
        "prognosis_ja": "中毒の予後は毒素の種類、曝露量、治療開始までの時間に依存する。早期の除染と支持療法で軽度中毒は予後良好。重度中毒や臓器障害がある場合は予後慎重〜不良。原因毒素の特定と除去が最優先。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
