    {
        "name": "Campylobacteriosis",
        "name_ja": "カンピロバクター症",
        "symptoms": {"abdominal_pain", "appetite_loss", "dehydration", "diarrhea", "lethargy"},
        "description": "Campylobacteriosis is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "カンピロバクター属による細菌性腸炎で、水様から血液混じりの下痢を引き起こします。人獣共通感染症の可能性があります。",
        "urgency": "high",
        "recommended_tests": ["fecal_culture", "physical_exam", "blood_chemistry"],
        "causes": "Bacterial enteritis caused by Campylobacter species, causing watery to bloody diarrhea. Zoonotic potential.",
        "causes_ja": "ハムスターにおけるカンピロバクター症の原因: カンピロバクター属による細菌性腸炎で、水様から血液混じりの下痢を引き起こします。人獣共通感染症の可能性があります。",
        "pathophysiology": "Bacterial enteritis caused by Campylobacter species, causing watery to bloody diarrhea. Zoonotic potential. Pathogenic bacteria colonize tissues through adhesion factors and invade via virulence mechanisms including toxin production, enzyme secretion, and immune evasion strategies. The resulting inflammatory cascade involves neutrophil infiltration, cytokine release, and complement activation. Tissue damage results from both direct bacterial action and the host's inflammatory response. Abscess formation, septicemia, or chronic granulomatous inflammation may develop depending on the organism and host immune status.",
        "pathophysiology_ja": "カンピロバクター症はハムスターにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "Appropriate medical or surgical intervention based on diagnosis, supportive care with IV fluids as needed, pain management, nutritional support, and regular monitoring of treatment response.",
        "treatment_ja": "ハムスターにおけるカンピロバクター症の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "カンピロバクター症の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "Prognosis depends on disease severity, timeliness of intervention, and response to treatment. Early diagnosis and appropriate therapy generally improve outcomes.",
        "prognosis_ja": "カンピロバクター症の予後: 早期発見と適切な治療で多くの疾患は予後良好。慢性疾患は定期的モニタリングと治療調整で長期管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
